import numpy as np
import itertools

def ket(dim, j):
    """
    Return a standard basis vector |j> in d-dimensional space.
    If `dim` is an int and `j` is an int, return the single basis vector.
    If `dim` is an int and `j` is a list, return the tensor product of
    |j_1>, |j_2>, ..., |j_n> where each |j_k> is a d-dimensional basis vector.
    If `dim` is a list [d1, d2, ..., dn] and `j` is a list of the same length,
    return the tensor product of |j_k> in d_k-dimensional space for each k.
    """
    # Helper to create a single basis vector
    def single_basis(d, idx):
        vec = np.zeros((d, 1), dtype=float)
        vec[idx, 0] = 1.0
        return vec

    # Case 1: dim is int
    if isinstance(dim, int):
        if isinstance(j, int):
            return single_basis(dim, j)
        elif isinstance(j, list):
            # tensor product of identical dimension basis vectors
            vec = single_basis(dim, j[0])
            for idx in j[1:]:
                vec = np.kron(vec, single_basis(dim, idx))
            return vec
        else:
            raise TypeError("j must be int or list when dim is int")

    # Case 2: dim is list
    elif isinstance(dim, list):
        if not isinstance(j, list):
            raise TypeError("j must be a list when dim is a list")
        if len(dim) != len(j):
            raise ValueError("dim and j must have the same length")
        vec = single_basis(dim[0], j[0])
        for d, idx in zip(dim[1:], j[1:]):
            vec = np.kron(vec, single_basis(d, idx))
        return vec

    else:
        raise TypeError("dim must be int or list")
